"""Independent byte-level HTTP/1.1 capture parser for cross-checking."""
import re

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")
MAX = (1 << 63) - 1
BAD = ('syntax', None)
INC = ('incomplete', None)


def parse(data):
    """Return (requests, error) with requests as plain dicts."""
    pos = 0
    total = len(data)
    requests = []

    def read_line():
        nonlocal pos
        limit = min(pos + 8194, total)
        index = data.find(b'\n', pos, limit)
        if index < 0:
            if total - pos >= 8194:
                raise ChannelFail('syntax')
            raise ChannelFail('incomplete')
        if index == pos or data[index - 1] != 0x0d:
            raise ChannelFail('syntax')
        content = data[pos:index - 1]
        if len(content) > 8192:
            raise ChannelFail('syntax')
        pos = index + 1
        return content

    def read_field(content):
        colon = content.find(b':')
        if colon <= 0:
            raise ChannelFail('syntax')
        name = content[:colon]
        if not TOKEN.fullmatch(name):
            raise ChannelFail('syntax')
        value = content[colon + 1:]
        for byte in value:
            if not (0x20 <= byte <= 0x7e or byte == 0x09):
                raise ChannelFail('syntax')
        return name, value.strip(b' \t')

    while pos < total:
        start = pos
        try:
            line = read_line()
            parts = line.split(b' ')
            if len(parts) != 3:
                raise ChannelFail('syntax')
            method, target, version = parts
            if not TOKEN.fullmatch(method) or not target:
                raise ChannelFail('syntax')
            for byte in target:
                if not 0x21 <= byte <= 0x7e:
                    raise ChannelFail('syntax')
            if version != b'HTTP/1.1':
                raise ChannelFail('syntax')
            block = len(line) + 2
            fields = []
            while True:
                line = read_line()
                block += len(line) + 2
                if block > 65536:
                    raise ChannelFail('syntax')
                if not line:
                    break
                if len(fields) >= 128:
                    raise ChannelFail('syntax')
                fields.append(read_field(line))
            hosts = [v for n, v in fields if n.lower() == b'host']
            cls = []
            for name, value in fields:
                if name.lower() == b'content-length':
                    members = [m.strip(b' \t') for m in value.split(b',')]
                    if not members or any(not m or not m.isdigit() for m in members):
                        raise ChannelFail('syntax')
                    if any(int(m) > MAX for m in members):
                        raise ChannelFail('syntax')
                    if len(set(int(m) for m in members)) != 1:
                        raise ChannelFail('syntax')
                    cls.append(int(members[0]))
            tes = [v for n, v in fields if n.lower() == b'transfer-encoding']
            if tes:
                if len(tes) > 1 or cls or tes[0].lower() != b'chunked':
                    raise ChannelFail('syntax')
                framing = 'chunked'
            elif cls:
                if len(set(cls)) != 1:
                    raise ChannelFail('syntax')
                framing = 'length'
            else:
                framing = 'none'
            body = b''
            trailers = []
            if framing == 'length':
                length = cls[0]
                if pos + length > total:
                    raise ChannelFail('incomplete')
                body = data[pos:pos + length]
                pos += length
            elif framing == 'chunked':
                while True:
                    line = read_line()
                    semi = line.find(b';')
                    if semi >= 0:
                        size = line[:semi]
                        for byte in line[semi + 1:]:
                            if not (0x20 <= byte <= 0x7e or byte == 0x09):
                                raise ChannelFail('syntax')
                    else:
                        size = line
                    if not size or not all(c in b'0123456789abcdefABCDEF' for c in size):
                        raise ChannelFail('syntax')
                    value = int(size, 16)
                    if value > MAX:
                        raise ChannelFail('syntax')
                    if value == 0:
                        tsize = 0
                        while True:
                            line = read_line()
                            tsize += len(line) + 2
                            if tsize > 65536:
                                raise ChannelFail('syntax')
                            if not line:
                                break
                            if len(trailers) >= 128:
                                raise ChannelFail('syntax')
                            name, val = read_field(line)
                            if name.lower() in (b'host', b'content-length',
                                                b'transfer-encoding'):
                                raise ChannelFail('syntax')
                            trailers.append((name, val))
                        break
                    if pos + value > total:
                        raise ChannelFail('incomplete')
                    body += data[pos:pos + value]
                    pos += value
                    if pos + 2 > total:
                        raise ChannelFail('incomplete')
                    if data[pos:pos + 2] != b'\r\n':
                        raise ChannelFail('syntax')
                    pos += 2
            requests.append({'start': start, 'end': pos, 'method': method,
                             'target': target, 'host_count': len(hosts),
                             'host': hosts[0].lower() if len(hosts) == 1 else b'',
                             'fields': fields, 'body': body, 'trailers': trailers,
                             'framing': framing})
        except ChannelFail as exc:
            return requests, {'kind': exc.kind, 'offset': start}
    return requests, None


class ChannelFail(Exception):
    def __init__(self, kind):
        super().__init__(kind)
        self.kind = kind
